#!/usr/bin/env python3
"""
Paper 6 - pre-outcome technical validation/amendment of frozen TARGET runner.

05f2c is a TECHNICAL contract-alignment stage performed BEFORE the first
reserved TARGET outcome value is read.

Scientific contract changes: NONE.

Why it exists
-------------
05f1c froze:
- if <5000 valid patient-cluster bootstrap draws are obtainable under the
  frozen support rules -> CI_NOT_ASSESSABLE and branch T-D;
- if a branch-defining point metric is not assessable -> T-D.

The 05f2b v1 runner instead hard-raised RuntimeError in those cases. This is an
execution mismatch with the already-frozen 05f1c protocol.

05f2c:
1. verifies the exact PASS 05f2b v1 contract and runner SHA;
2. leaves all DOG2 source artifacts byte-identical;
3. writes runner v2 with ONLY fail->T-D/CI_NOT_ASSESSABLE alignment;
4. syntax-checks/imports/preflights runner v2;
5. performs a deterministic SYNTHETIC structural smoke test of all
   T0-T2/N0-N5 fold callables using fake expression/outcome values;
6. freezes runner v2 SHA before any TARGET OS values are opened.

No TARGET clinical values are read.
No TARGET outcomes are read.
No real human model is fitted.
No GSE21257/GSE39055 outcomes are read.
CPU only.
"""

from __future__ import annotations

import ast
import base64
import hashlib
import importlib.util
import json
import sys
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Dict

import numpy as np

try:
    import torch
except ImportError as exc:
    raise ImportError("05f2c requires PyTorch.") from exc


SCRIPT_VERSION = (
    "05f2c-preoutcome-validate-amend-target-runner-v2-smoke-fixture-fix-no-cli"
)
CONTRACT_VERSION = (
    "paper6-target-runner-technical-contract-alignment-v2-smoke-fixture-fix"
)

ROOT = Path(__file__).resolve().parents[1]

F2B_DIR = ROOT / "results" / "human_posthold_descriptive" / "05f2b"
F2B_CONTRACT = F2B_DIR / "source_artifacts_and_final_runner_contract.json"
F2B_SUMMARY = F2B_DIR / "summary.json"
F2B_RUNNER = F2B_DIR / "runner" / "frozen_TARGET_evaluation_runner.py"
F2B_SOURCE_REP = (
    F2B_DIR / "source_artifacts" / "DOG2_full_source_Hallmark50_representation.npz"
)
F2B_SOURCE_CLASSICAL = (
    F2B_DIR / "source_artifacts" / "DOG2_full_source_classical_ridge.npz"
)
F2B_SOURCE_NEURAL = (
    F2B_DIR / "source_artifacts" / "DOG2_full_source_neural_mlp.npz"
)

EXPECTED_F2B_CONTRACT_SHA256 = (
    "1c9780214a917216cc2dcb39dfa708fc43912c47a7b325e4b6a62ba81ca2b3fc"
)
EXPECTED_F2B_RUNNER_SHA256 = (
    "eff1269e3f8270b37e0ef5581eff9cbabf8f6ca089b093de924d8266e6058890"
)
EXPECTED_F2B_STATUS = (
    "PASS_DOG2_SOURCE_ARTIFACTS_AND_FINAL_TARGET_RUNNER_FROZEN"
)

F1C_DIR = ROOT / "results" / "human_posthold_descriptive" / "05f1c_v2"
F1C_RESAMPLING = F1C_DIR / "TARGET_resampling_and_CI_contract.json"

EXPECTED_F1C_RESAMPLING_SHA256 = (
    "0d6d004b2ea7007c0fde853ff10d97e0df734ea4571f1d55bc2efcfef9367e68"
)

OUT_DIR = ROOT / "results" / "human_posthold_descriptive" / "05f2c_v2"
RUNNER_DIR = OUT_DIR / "runner"
OUT_DIR.mkdir(parents=True, exist_ok=True)
RUNNER_DIR.mkdir(parents=True, exist_ok=True)

RUNNER_V2 = RUNNER_DIR / "frozen_TARGET_evaluation_runner_v2.py"
SMOKE_JSON = OUT_DIR / "synthetic_runner_smoke_test.json"
CONTRACT_JSON = OUT_DIR / "technical_runner_amendment_contract.json"
SUMMARY_JSON = OUT_DIR / "summary.json"

RUNNER_V2_SOURCE_B64 = ""


def now_utc() -> str:
    return datetime.now(timezone.utc).isoformat()


def clean(value: Any) -> str:
    return "" if value is None else str(value).strip()


def require_file(path: Path) -> Path:
    if not path.exists() or not path.is_file():
        raise FileNotFoundError(path)
    return path


def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            h.update(block)
    return h.hexdigest()


def read_json(path: Path) -> Any:
    with path.open("r", encoding="utf-8") as handle:
        return json.load(handle)


def write_json(path: Path, payload: Any) -> None:
    with path.open("w", encoding="utf-8", newline="\n") as handle:
        json.dump(payload, handle, indent=2, sort_keys=True)
        handle.write("\n")


def load_module(path: Path, name: str):
    spec = importlib.util.spec_from_file_location(name, path)
    if spec is None or spec.loader is None:
        raise RuntimeError(f"Could not import {path}")
    module = importlib.util.module_from_spec(spec)
    prior = sys.modules.get(name)
    sys.modules[name] = module
    try:
        spec.loader.exec_module(module)
    except Exception:
        if prior is None:
            sys.modules.pop(name, None)
        else:
            sys.modules[name] = prior
        raise
    return module


def main() -> None:
    started = now_utc()

    print("=" * 120)
    print("Paper 6 - pre-outcome technical validation/amendment of TARGET runner")
    print("=" * 120)
    print(f"Script version: {SCRIPT_VERSION}")
    print()
    print("Safety / scope:")
    print("  TARGET clinical file read: NO")
    print("  TARGET OS event/time values read: NO")
    print("  Real human outcomes read: NO")
    print("  Real TARGET models fit: NO")
    print("  Synthetic fake-data runner smoke fit: YES")
    print("  DOG2 source artifacts changed: NO")
    print("  Scientific model/metric/branch rules changed: NO")
    print("  Technical recovery from 05f2c v1 smoke-fixture error: YES")
    print("  Real TARGET values used by failed v1: NO")
    print("  GPU execution: NO")
    print()

    for path in [
        F2B_CONTRACT,
        F2B_SUMMARY,
        F2B_RUNNER,
        F2B_SOURCE_REP,
        F2B_SOURCE_CLASSICAL,
        F2B_SOURCE_NEURAL,
        F1C_RESAMPLING,
    ]:
        require_file(path)

    if sha256_file(F2B_CONTRACT) != EXPECTED_F2B_CONTRACT_SHA256:
        raise RuntimeError("05f2b contract hash changed.")
    if sha256_file(F2B_RUNNER) != EXPECTED_F2B_RUNNER_SHA256:
        raise RuntimeError("05f2b runner hash changed.")
    if sha256_file(F1C_RESAMPLING) != EXPECTED_F1C_RESAMPLING_SHA256:
        raise RuntimeError("05f1c resampling contract hash changed.")

    f2b = read_json(F2B_SUMMARY)
    f2b_contract = read_json(F2B_CONTRACT)

    if clean(f2b.get("scientific_status")) != EXPECTED_F2B_STATUS:
        raise RuntimeError("05f2b is not in the expected PASS state.")
    if f2b.get("TARGET_OS_event_values_read") is not False:
        raise RuntimeError("05f2b provenance indicates TARGET event access.")
    if f2b.get("TARGET_OS_time_values_read") is not False:
        raise RuntimeError("05f2b provenance indicates TARGET time access.")

    source_hashes_before = {
        "source_representation": sha256_file(F2B_SOURCE_REP),
        "source_classical": sha256_file(F2B_SOURCE_CLASSICAL),
        "source_neural": sha256_file(F2B_SOURCE_NEURAL),
    }

    expected_source = {
        "source_representation": clean(
            (f2b_contract.get("source_representation") or {}).get("sha256")
        ),
        "source_classical": clean(
            (f2b_contract.get("source_classical") or {}).get("sha256")
        ),
        "source_neural": clean(
            (f2b_contract.get("source_neural") or {}).get("sha256")
        ),
    }

    for key in source_hashes_before:
        if source_hashes_before[key] != expected_source[key]:
            raise RuntimeError(f"05f2b source artifact changed: {key}")

    runner_text = base64.b64decode(
        RUNNER_V2_SOURCE_B64.encode("ascii")
    ).decode("utf-8")

    # Fill the same exact source/script hash dictionary already embedded in v1.
    v1_runner_text = F2B_RUNNER.read_text(encoding="utf-8")
    marker = "EXPECTED_HASHES = "
    pos = v1_runner_text.find(marker)
    if pos < 0:
        raise RuntimeError("Could not locate EXPECTED_HASHES in v1 runner.")
    line = v1_runner_text[pos:].splitlines()[0]
    expected_hash_literal = line[len(marker):]

    runner_text = runner_text.replace(
        "__EXPECTED_HASHES__",
        expected_hash_literal,
    )

    ast.parse(runner_text, filename=str(RUNNER_V2))
    RUNNER_V2.write_text(runner_text, encoding="utf-8")

    runner = load_module(
        RUNNER_V2,
        "paper6_target_runner_v2_preoutcome_smoke",
    )

    preflight = runner.preflight()
    if clean(preflight.get("status")) != "PASS":
        raise RuntimeError("Runner v2 preflight failed.")

    # ------------------------------------------------------------------
    # Deterministic fake-data structural smoke.
    # No real TARGET values are used.
    # ------------------------------------------------------------------
    rng = np.random.default_rng(20260830)

    n_train = 60
    n_test = 28
    p = 11815

    X_train = rng.normal(
        0.0,
        1.0,
        size=(n_train, p),
    ).astype(np.float64)

    X_test = rng.normal(
        0.0,
        1.0,
        size=(n_test, p),
    ).astype(np.float64)

    train_time = (
        np.linspace(30.0, 1200.0, n_train)
        + rng.uniform(0.0, 0.1, size=n_train)
    )

    train_event = np.asarray(
        [1, 0] * (n_train // 2),
        dtype=bool,
    )

    device = torch.device("cpu")
    runner_module_04c, _ = runner._modules()

    fitted = runner.fit_predict_fold(
        X_train,
        X_test,
        train_time,
        train_event,
        repeat=0,
        outer_fold=0,
        device=device,
    )

    expected_models = runner.MODEL_IDS

    for model in expected_models:
        train_risk = np.asarray(
            fitted["risk_train"][model],
            dtype=float,
        )
        test_risk = np.asarray(
            fitted["risk_test"][model],
            dtype=float,
        )

        if train_risk.shape != (n_train,):
            raise RuntimeError(
                f"Synthetic smoke {model}: train risk shape {train_risk.shape}"
            )
        if test_risk.shape != (n_test,):
            raise RuntimeError(
                f"Synthetic smoke {model}: test risk shape {test_risk.shape}"
            )
        if not np.isfinite(train_risk).all():
            raise RuntimeError(f"Synthetic smoke {model}: train risk nonfinite.")
        if not np.isfinite(test_risk).all():
            raise RuntimeError(f"Synthetic smoke {model}: test risk nonfinite.")

    test_time = (
        np.linspace(40.0, 900.0, n_test)
        + rng.uniform(0.0, 0.1, size=n_test)
    )
    test_event = np.asarray(
        [1, 0] * (n_test // 2),
        dtype=bool,
    )

    metric_smoke = runner._fold_metrics(
        runner_module_04c,
        train_time,
        train_event,
        test_time,
        test_event,
        fitted["risk_train"]["N0"],
        fitted["risk_test"]["N0"],
    )

    if not np.isfinite(float(metric_smoke["uno_c"])):
        raise RuntimeError("Synthetic smoke fold Uno-C nonfinite.")

    # Mechanical T-D rule smoke.
    fake_summary = __import__("pandas").DataFrame(
        [
            # Deliberately constructed to satisfy frozen T-A point rules:
            # N0=.51 > .50
            # N1-N0=.01 < +.02
            # N0-T0=.01 > -.02
            {"model_id": "T0", "uno_c": 0.50},
            {"model_id": "T1", "uno_c": 0.56},
            {"model_id": "T2", "uno_c": 0.56},
            {"model_id": "N0", "uno_c": 0.51},
            {"model_id": "N1", "uno_c": 0.52},
            {"model_id": "N2", "uno_c": 0.52},
            {"model_id": "N3", "uno_c": 0.55},
            {"model_id": "N4", "uno_c": 0.54},
            {"model_id": "N5", "uno_c": 0.54},
        ]
    )

    fake_lookup = (
        fake_summary
        .set_index("model_id")["uno_c"]
        .to_dict()
    )
    fake_d_n1_n0 = float(fake_lookup["N1"] - fake_lookup["N0"])
    fake_d_n0_t0 = float(fake_lookup["N0"] - fake_lookup["T0"])

    if not (
        float(fake_lookup["N0"]) > 0.50
        and fake_d_n1_n0 < +0.02
        and fake_d_n0_t0 > -0.02
    ):
        raise RuntimeError(
            "Synthetic T-A fixture itself does not satisfy frozen T-A "
            f"conditions: N0={fake_lookup['N0']}, "
            f"N1-N0={fake_d_n1_n0}, N0-T0={fake_d_n0_t0}."
        )

    candidate = runner._candidate_branch(fake_summary)
    if candidate != "T-A":
        raise RuntimeError(
            f"Synthetic branch smoke expected T-A candidate, got {candidate}."
        )

    model_ci = {"N0": (0.49, 0.53)}
    delta_ci = {
        "N1-N0": (-0.01, 0.015),
        "N0-T0": (-0.06, 0.01),
    }

    td = runner._final_branch_with_uncertainty(
        candidate,
        model_ci,
        delta_ci,
    )

    if td != "T-D":
        raise RuntimeError(
            f"Synthetic uncertainty smoke expected T-D, got {td}."
        )

    source_hashes_after = {
        "source_representation": sha256_file(F2B_SOURCE_REP),
        "source_classical": sha256_file(F2B_SOURCE_CLASSICAL),
        "source_neural": sha256_file(F2B_SOURCE_NEURAL),
    }

    if source_hashes_after != source_hashes_before:
        raise RuntimeError(
            "05f2c altered a frozen DOG2 source artifact."
        )

    smoke = {
        "status": "PASS",
        "created_utc": now_utc(),
        "fake_train_n": n_train,
        "fake_test_n": n_test,
        "fake_features": p,
        "models_exercised": expected_models,
        "all_model_risks_finite": True,
        "fold_uno_c_finite": True,
        "fold_ibs_status": metric_smoke["ibs_status"],
        "candidate_branch_smoke": candidate,
        "synthetic_TA_fixture": {
            "T0": float(fake_lookup["T0"]),
            "N0": float(fake_lookup["N0"]),
            "N1": float(fake_lookup["N1"]),
            "N1_minus_N0": fake_d_n1_n0,
            "N0_minus_T0": fake_d_n0_t0,
            "frozen_TA_conditions_satisfied_before_call": True,
        },
        "uncertainty_override_smoke": td,
        "TARGET_values_used": False,
        "device": "cpu",
    }
    write_json(SMOKE_JSON, smoke)

    contract = {
        "script_version": SCRIPT_VERSION,
        "contract_version": CONTRACT_VERSION,
        "status": "PASS",
        "scientific_status": (
            "PASS_TARGET_RUNNER_V2_TECHNICALLY_VALIDATED_PREOUTCOME"
        ),
        "created_utc": now_utc(),

        "upstream_05f2b_contract_sha256": EXPECTED_F2B_CONTRACT_SHA256,
        "upstream_05f2b_runner_sha256": EXPECTED_F2B_RUNNER_SHA256,
        "05f1c_resampling_contract_sha256": EXPECTED_F1C_RESAMPLING_SHA256,

        "technical_recovery_from_05f2c_v1": {
            "prior_failed_script_version": (
                "05f2c-preoutcome-validate-amend-target-runner-v1-no-cli"
            ),
            "failure_stage": "synthetic branch unit-smoke only",
            "failure_reason": (
                "fake fixture expected T-A but its N0-T0=-0.04 violated "
                "the frozen T-A requirement N0-T0>-0.02"
            ),
            "runner_branch_logic_was_correct": True,
            "all_model_fold_callables_had_already_executed_before_failure": True,
            "TARGET_values_read_before_failure": False,
            "scientific_contract_changed": False,
            "fix": (
                "change fake T0 from 0.55 to 0.50 so the fixture actually "
                "satisfies the already-frozen T-A conditions"
            ),
        },

        "technical_amendment": {
            "scientific_contract_changed": False,
            "models_changed": False,
            "hyperparameters_changed": False,
            "metrics_changed": False,
            "branch_rules_changed": False,
            "bootstrap_sampling_rule_changed": False,
            "changes": [
                (
                    "branch-defining point metric not assessable: "
                    "v1 RuntimeError -> frozen T-D"
                ),
                (
                    "<5000 valid bootstrap draws after 25000 attempts: "
                    "v1 RuntimeError -> CI_NOT_ASSESSABLE + frozen T-D"
                ),
            ],
            "reason": (
                "align runner execution exactly with already-frozen "
                "05f1c NOT_ASSESSABLE/T-D contract"
            ),
        },

        "source_artifacts": source_hashes_before,

        "runner_v2": {
            "path": str(RUNNER_V2.relative_to(ROOT)),
            "sha256": sha256_file(RUNNER_V2),
            "preflight": preflight,
            "synthetic_smoke_test_sha256": sha256_file(SMOKE_JSON),
        },

        "outcome_opening_authorization": {
            "TARGET_endpoint_values_may_be_read_after_05f2c_PASS": True,
            "authoritative_runner": str(RUNNER_V2.relative_to(ROOT)),
            "authoritative_runner_sha256": sha256_file(RUNNER_V2),
            "05f2b_v1_runner_superseded_for_execution": True,
            "05f2b_source_artifacts_remain_authoritative": True,
            "allowed_endpoint_columns": [
                "case_submitter_id",
                "os_event",
                "os_time_days",
            ],
        },

        "safety": {
            "TARGET_clinical_file_read": False,
            "TARGET_OS_event_values_read": False,
            "TARGET_OS_time_values_read": False,
            "TARGET_secondary_endpoint_values_read": False,
            "real_human_models_fit": False,
            "synthetic_fake_data_smoke_fit": True,
            "DOG2_source_artifacts_changed": False,
            "GSE21257_outcomes_read": False,
            "GSE39055_outcomes_read": False,
            "GPU_execution": False,
        },

        "next": (
            "05f3 first reserved TARGET-OS outcome opening using ONLY the "
            "SHA-locked 05f2c runner v2 and frozen 05f1c endpoint parser."
        ),
    }

    write_json(CONTRACT_JSON, contract)

    summary = {
        "script_version": SCRIPT_VERSION,
        "status": "PASS",
        "scientific_status": contract["scientific_status"],
        "run_started_utc": started,
        "run_finished_utc": now_utc(),
        "scientific_contract_changed": False,
        "technical_recovery_from_05f2c_v1": True,
        "05f2c_v1_TARGET_values_read": False,
        "runner_v2_sha256": sha256_file(RUNNER_V2),
        "synthetic_smoke_test": "PASS",
        "TARGET_OS_event_values_read": False,
        "TARGET_OS_time_values_read": False,
        "TARGET_endpoint_values_may_be_read_after_this_PASS": True,
        "source_artifacts_unchanged": True,
        "contract_sha256": sha256_file(CONTRACT_JSON),
        "next": contract["next"],
    }
    write_json(SUMMARY_JSON, summary)

    print("=" * 120)
    print("05f2c PRE-OUTCOME RUNNER VALIDATION SUMMARY")
    print("=" * 120)
    print("Technical recovery:")
    print("  05f2c v1 failed only because fake branch fixture was internally inconsistent")
    print("  frozen branch logic changed: NO")
    print("  fake T-A fixture corrected: YES")
    print("  TARGET values read by v1: NO")
    print()
    print("05f2b source artifacts byte-identical: PASS")
    print("Scientific model/hyperparameter rules changed: NO")
    print("Scientific metric rules changed: NO")
    print("Branch definitions changed: NO")
    print()
    print("Technical alignment:")
    print("  non-assessable branch metric -> T-D: FIXED")
    print("  insufficient bootstrap valid draws -> CI_NOT_ASSESSABLE + T-D: FIXED")
    print()
    print("Synthetic structural smoke:")
    print("  T0-T2/N0-N5 all exercised: PASS")
    print("  all train/test risks finite: PASS")
    print("  fold Uno-C adapter: PASS")
    print(f"  fold IBS adapter status: {metric_smoke['ibs_status']}")
    print("  T-D uncertainty rule: PASS")
    print("  real TARGET values used: NO")
    print()
    print(f"Runner v2 SHA256: {sha256_file(RUNNER_V2)}")
    print()
    print("TARGET OS event/time values read: NO")
    print("TARGET endpoint values may be read AFTER THIS PASS: YES")
    print()
    print("Next: 05f3 FIRST reserved TARGET-OS outcome opening.")
    print("=" * 120)
    print("05f2c: PASS_TARGET_RUNNER_V2_TECHNICALLY_VALIDATED_PREOUTCOME")
    print("=" * 120)


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        print()
        print("=" * 120, file=sys.stderr)
        print("05f2c pre-outcome runner validation: FAIL", file=sys.stderr)
        print(f"{type(exc).__name__}: {exc}", file=sys.stderr)
        print("=" * 120, file=sys.stderr)
        raise
